#include <string>
#include <vector>
#include <unordered_map>
#include <cctype>

class Solution {
public:
    std::vector<int> countValidWordOccurrences(std::vector<std::string>& chunks, std::vector<std::string>& queries) {
        std::string s;
        for (const auto& c : chunks) s += c;
        int n = s.length();
        std::unordered_map<std::string, int> counts;
        std::string cur;
        for (int i = 0; i < n; ++i) {
            char c = s[i];
            if (std::islower(c)) {
                cur += c;
            } else if (c == '-') {
                if (i > 0 && i + 1 < n && std::islower(s[i - 1]) && std::islower(s[i + 1])) {
                    cur += c;
                } else {
                    if (!cur.empty()) {
                        counts[cur]++;
                        cur.clear();
                    }
                }
            } else {
                if (!cur.empty()) {
                    counts[cur]++;
                    cur.clear();
                }
            }
        }
        if (!cur.empty()) counts[cur]++;
        std::vector<int> ans;
        for (const auto& q : queries) ans.push_back(counts[q]);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] countValidWordOccurrences(String[] chunks, String[] queries) {
        StringBuilder sb = new StringBuilder();
        for (String c : chunks) sb.append(c);
        String s = sb.toString();
        int n = s.length();
        Map<String, Integer> counts = new HashMap<>();
        StringBuilder cur = new StringBuilder();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                cur.append(c);
            } else if (c == '-') {
                if (i > 0 && i + 1 < n && Character.isLowerCase(s.charAt(i - 1)) && Character.isLowerCase(s.charAt(i + 1))) {
                    cur.append(c);
                } else {
                    if (cur.length() > 0) {
                        counts.put(cur.toString(), counts.getOrDefault(cur.toString(), 0) + 1);
                        cur.setLength(0);
                    }
                }
            } else {
                if (cur.length() > 0) {
                    counts.put(cur.toString(), counts.getOrDefault(cur.toString(), 0) + 1);
                    cur.setLength(0);
                }
            }
        }
        if (cur.length() > 0) {
            counts.put(cur.toString(), counts.getOrDefault(cur.toString(), 0) + 1);
        }
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            ans[i] = counts.getOrDefault(queries[i], 0);
        }
        return ans;
    }
}

