    const s = chunks.join('');
    const n = s.length;
    const counts = new Map();
    let cur = [];
    for (let i = 0; i < n; i++) {
        const c = s[i];
        if (c >= 'a' && c <= 'z') {
            cur.push(c);
        } else if (c === '-') {
            if (i > 0 && i + 1 < n && s[i - 1] >= 'a' && s[i - 1] <= 'z' && s[i + 1] >= 'a' && s[i + 1] <= 'z') {
                cur.push(c);
            } else {
                if (cur.length > 0) {
                    const w = cur.join('');
                    counts.set(w, (counts.get(w) || 0) + 1);
                    cur = [];
                }
            }
        } else {
            if (cur.length > 0) {
                const w = cur.join('');
                counts.set(w, (counts.get(w) || 0) + 1);
                cur = [];
            }
        }
    }
    if (cur.length > 0) {
        const w = cur.join('');
        counts.set(w, (counts.get(w) || 0) + 1);
    }
    return queries.map(q => counts.get(q) || 0);
